// A unit in which a table declares `forms` is generated by Go alone: every
// other target refuses it by name, centrally (docs/SPEC-TABLES.md §2.11).
package compiler

import (
	"strings"
	"testing"

	"github.com/mas-bandwidth/schema/v2/ir"

	"github.com/mas-bandwidth/schema/v2/internal/check"
	"github.com/mas-bandwidth/schema/v2/internal/parser"
)

func TestDeclaredFormsAreRefusedByEveryTargetButGo(t *testing.T) {
	t.Parallel()
	src := "package probe\nfixed table Pong | forms = \"wire\"\n{\n    seq int32\n}\n"
	f, perrs := parser.Parse("Probe.schema", []byte(src))
	if len(perrs) > 0 {
		t.Fatalf("parse: %v", perrs[0])
	}
	u, cerrs := check.Unit([]check.SourceFile{{Path: "Probe.schema", Name: "Probe.schema", Base: "Probe", Bytes: []byte(src), AST: f}})
	if len(cerrs) > 0 {
		t.Fatalf("check: %v", cerrs[0])
	}
	c := New()
	for _, target := range c.Targets() {
		_, err := c.Generate(u, target, nil)
		if target == "go" {
			if err != nil {
				t.Errorf("go refused a declaration it carries: %v", err)
			}
			continue
		}
		for _, want := range []string{"table Pong declares forms", "the " + target + " target", "Go carries it first"} {
			if err == nil || !strings.Contains(err.Error(), want) {
				t.Errorf("%s: error %v, want one containing %q", target, err, want)
			}
		}
	}
}

const declaredFormsSrc = `package probe

fixed table Both | forms = "wire,json"
{
    a int32
}

fixed table WireOnly | forms = "wire"
{
    b int32
}

fixed table Plain
{
    c int32
}
`

func declaredFormsUnit(t *testing.T, src string) *ir.Unit {
	t.Helper()
	f, perrs := parser.Parse("Probe.schema", []byte(src))
	if len(perrs) > 0 {
		t.Fatalf("parse: %v", perrs[0])
	}
	u, cerrs := check.Unit([]check.SourceFile{{Path: "Probe.schema", Name: "Probe.schema", Base: "Probe", Bytes: []byte(src), AST: f}})
	if len(cerrs) > 0 {
		t.Fatalf("check: %v", cerrs[0])
	}
	return u
}

// The intersection with a generate-time surface (docs/SPEC-TABLES.md §2.11).
func TestSurfaceIntersectsDeclaredForms(t *testing.T) {
	t.Parallel()
	u := declaredFormsUnit(t, declaredFormsSrc)
	cases := []struct {
		table   string
		surface []string
		want    string // the forms carried, comma-joined
		refuse  string // a substring of the refusal, when one is due
	}{
		{"Both", nil, "wire,json", ""},
		{"Plain", nil, "wire,json", ""},
		{"WireOnly", nil, "wire", ""},
		{"Both", []string{"json"}, "json", ""},
		{"Plain", []string{"wire"}, "wire", ""},
		{"WireOnly", []string{"wire"}, "wire", ""},
		{"WireOnly", []string{"json"}, "", "table WireOnly does not declare it"},
		{"WireOnly", []string{"wire", "json"}, "", "surface names form json"},
		{"Both", []string{"cook"}, "", "not a form"},
	}
	for _, c := range cases {
		got, err := ir.SurfaceForms(u.Tables[c.table], c.surface)
		if c.refuse != "" {
			if err == nil || !strings.Contains(err.Error(), c.refuse) {
				t.Errorf("%s %v: error %v, want one containing %q", c.table, c.surface, err, c.refuse)
			}
			continue
		}
		if err != nil || strings.Join(got, ",") != c.want {
			t.Errorf("%s %v: got %v, %v, want %s", c.table, c.surface, got, err, c.want)
		}
	}
}
